sub add {
  my ($self, $name) = (shift, shift);

  # Make sure we have a headers array
  my $headers = $self->{headers} ||= [];

  # Store the original case for the header name
  my $lc = lc $name;
  $self->{normalcase}{$lc} //= $name;

  # Add one entry per value
  push @$headers, [$lc, $_] for @_;

  return $self;
}
