sub parse {
  my ($self, $template) = @_;

  # Clean start
  my $tree = $self->{tree} = [];
  $self->unparsed($template);

  my $tag_start    = $self->tag_start;
  my $tag_end      = $self->tag_end;
  my $line_start   = $self->line_start;
  my $replace_mark = $self->replace_mark;
  my $expr_mark    = $self->expression_mark;
  my $esc_mark     = $self->escape_mark;
  my $comment_mark = $self->comment_mark;
  my $trim_mark    = $self->trim_mark;
  my $capture_start = $self->capture_start;
  my $capture_end   = $self->capture_end;

  my $line_re = qr/^(\s*)\Q$line_start\E(?:(\Q$replace_mark\E)|(\Q$comment_mark\E)|(\Q$esc_mark\E\Q$expr_mark\E)|(\Q$expr_mark\E))?(.*)$/;
  my $token_re = qr/
    (
      \Q$tag_start\E(?:\Q$replace_mark\E)  # Escaped tag
      |
      \Q$tag_start\E                        # Tag start
      |
      (?:\Q$trim_mark\E)?\Q$tag_end\E       # Tag end (with optional trim)
    )
  /x;

  my $state = 'text';
  my $trimming = 0;
  my $tag_type = '';

  my @lines = split /\n/, $template, -1;
  # Remove empty trailing lines
  while (@lines && $lines[-1] eq '') { pop @lines }

  for my $j (0 .. $#lines) {
    my $line = $lines[$j];
    my $newline = $j < $#lines ? 1 : 0;

    # Perl line
    if ($line =~ $line_re) {
      my ($ws, $replace, $comment, $esct, $expr, $code) = ($1, $2, $3, $4, $5, $6);

      push @$tree, ['text', $ws] if length $ws;

      if ($replace) {
        push @$tree, ['text', "$line_start$code"];
      } elsif ($comment) {
        # Comment line, ignore
      } elsif ($esct) {
        my $value = $code;
        $value =~ s/^\s+//;
        $value =~ s/\s+$//;
        push @$tree, _line_ops($self, 'esct', $value, $capture_start, $capture_end);
      } elsif ($expr) {
        my $value = $code;
        $value =~ s/^\s+//;
        $value =~ s/\s+$//;
        push @$tree, _line_ops($self, 'expr', $value, $capture_start, $capture_end);
      } else {
        my $value = $code;
        push @$tree, _line_ops($self, 'code', $value, $capture_start, $capture_end);
      }

      push @$tree, ['line'] if $newline;
      next;
    }

    # Mixed line (tags)
    my @tokens = split /(\Q$tag_start\E\Q$replace_mark\E|\Q$tag_start\E|\Q$trim_mark\E\Q$tag_end\E|\Q$tag_end\E)/, $line;

    for my $i (0 .. $#tokens) {
      my $token = $tokens[$i];
      next unless length $token;

      if ($state eq 'text') {
        if ($token eq "$tag_start$replace_mark") {
          push @$tree, ['text', $tag_start];
        } elsif ($token eq $tag_start) {
          $state = 'tag';
          $tag_type = '';
          # Peek at next token to determine tag type
          my $next = defined $tokens[$i + 1] ? $tokens[$i + 1] : '';
          if ($next =~ s/^(\Q$comment_mark\E)//) {
            $tag_type = 'comment';
            $tokens[$i + 1] = $next;
          } elsif ($next =~ s/^(\Q$esc_mark\E\Q$expr_mark\E)//) {
            $tag_type = 'esct';
            $tokens[$i + 1] = $next;
          } elsif ($next =~ s/^(\Q$expr_mark\E)//) {
            $tag_type = 'expr';
            $tokens[$i + 1] = $next;
          } else {
            $tag_type = 'code';
          }
        } else {
          $token =~ s/\\\\$/\\\\\n/ if $newline && $i == $#tokens;
          if ($newline && $i == $#tokens && $token =~ s/\\$//) {
            push @$tree, ['text', $token];
            next;
          }
          push @$tree, ['text', $token];
        }
      } elsif ($state eq 'tag') {
        if ($token eq "$trim_mark$tag_end") {
          $state = 'text';
          $trimming = 1;
        } elsif ($token eq $tag_end) {
          $state = 'text';
        } else {
          unless ($tag_type eq 'comment') {
            my $value = $token;
            # Handle capture blocks
            if ($tag_type eq 'code' || $tag_type eq 'expr' || $tag_type eq 'esct') {
              if ($value =~ s/\s*\Q$capture_end\E\s*$//) {
                push @$tree, ['cpen'];
              }
              my $has_cpst = $value =~ s/\s*\Q$capture_start\E\s*$//;
              push @$tree, [$tag_type, $value] if length $value;
              push @$tree, ['cpst'] if $has_cpst;
            }
          }
        }
      }
    }

    if ($trimming) {
      _trim($tree);
      $trimming = 0;
    }

    if ($newline && $state eq 'text') {
      push @$tree, ['text', "\n"];
    }
    push @$tree, ['line'] if $newline;
  }

  return $self;
}

sub _line_ops {
  my ($self, $type, $value, $capture_start, $capture_end) = @_;
  my @ops;

  if ($value =~ s/\s*\Q$capture_end\E\s*$//) {
    push @ops, ['cpen'];
  }
  my $has_cpst = $value =~ s/\s*\Q$capture_start\E\s*$//;
  push @ops, [$type, $value] if length $value || $type eq 'code';
  push @ops, ['cpst'] if $has_cpst;

  return @ops;
}
