sub network_contains {
  my ($cidr, $addr) = @_;

  # Parse network and prefix length
  my ($net_addr, $prefix_len) = split '/', $cidr, 2;

  # Determine address family for the network address
  my $net_family;
  my $net_packed;
  if ($net_addr =~ /:/) {
    $net_family = AF_INET6;
    $net_packed = inet_pton(AF_INET6, $net_addr);
  }
  else {
    $net_family = AF_INET;
    $net_packed = inet_pton(AF_INET, $net_addr);
  }
  return undef unless defined $net_packed;

  # Determine address family for the target address
  my $addr_family;
  my $addr_packed;
  if ($addr =~ /:/) {
    $addr_family = AF_INET6;
    $addr_packed = inet_pton(AF_INET6, $addr);
  }
  else {
    $addr_family = AF_INET;
    $addr_packed = inet_pton(AF_INET, $addr);
