sub punycode_encode {
  my $output = shift;
  use integer;

  my $n     = PC_INITIAL_N;
  my $delta = 0;
  my $bias  = PC_INITIAL_BIAS;

  # Extract basic code points and non-basic code points
  my @input = map {ord} split //, $output;
  my @basic = grep { $_ < 0x80 } @input;
  my $h = my $b = @basic;
  $output = join '', map {chr} @basic;
  $output .= '-' if $b > 0;

  # Main encoding loop
  while ($h < @input) {

    # Find the minimum code point >= n
    my $m = min grep { $_ >= $n } @input;

    $delta += ($m - $n) * ($h + 1);
    $n = $m;

    for my $c (@input) {
      if ($c < $n) {
        $delta++;
      }
      elsif ($c == $n) {
        my $q = $delta;
        for (my $k = PC_BASE; ; $k += PC_BASE) {
          my $t = $k <= $bias ? PC_TMIN : ($k >= $bias + PC_TMAX ? PC_TMAX : $k - $bias);
          last if $q < $t;
          my $o = $t + (($q - $t) % (PC_BASE - $t));
          $output .= chr $o + ($o < 26 ? 0x61 : 0x30 - 26);
          $q = ($q - $t) / (PC_BASE - $t);
