sub tablify {
  my $rows = shift;

  # Calculate the maximum width for each column (except the last)
  my @widths;
  for my $row (@$rows) {
    for my $i (0 .. $#$row) {
      my $len = length($row->[$i] // '');
      $widths[$i] = $len if !defined $widths[$i] || $len > $widths[$i];
    }
  }

  # Build the table
  my $table = '';
  for my $row (@$rows) {
    my @parts;
    for my $i (0 .. $#$row) {
      my $cell = $row->[$i] // '';
      # Pad all columns except the last one
      if ($i < $#$row) {
        push @parts, $cell . (' ' x ($widths[$i] - length($cell)));
      }
      else {
        push @parts, $cell;
      }
    }
    $table .= join('  ', @parts) . "\n";
  }

  return $table;
