sub new {
  my $self = shift->SUPER::new((ref $_[0] ? %{shift()} : @_), @Mojo::Server::ARGS_OVERRIDE);

  my $class = ref $self;
  my $home  = $self->home;

  # Detect home directory
  unless ($home->to_string) {
    $home = $self->home(Mojo::Home->new->detect($class))->home;
  }

  # Moniker
  $self->{moniker} //= Mojo::Util::decamelize($class =~ /^([^:]+)/ ? $1 : $class);

  # Log
  my $mode = $self->mode;
  my $log  = $self->log;
  $log->path($home->child('log', "$mode.log")) if -w $home->child('log');
  $log->level($ENV{MOJO_LOG_LEVEL}) if $ENV{MOJO_LOG_LEVEL};
  $log->level($mode eq 'development' ? 'trace' : 'info') unless $log->level;

  # Renderer and static file server
  $self->renderer->paths([
    $home->child('templates')->to_string
  ]) if -d $home->child('templates');
  $self->static->paths([
    $home->child('public')->to_string
  ]) if -d $home->child('public');

  # Default plugins
  $self->plugin('HeaderCondition');
  $self->plugin('DefaultHelpers');
  $self->plugin('TagHelpers');

  # Default exception handling
  $self->hook(
    around_dispatch => sub {
      my ($next, $c) = @_;
      my $res;
      eval { $next->(); 1 } or do {
        my $err = $@;
        $c->helpers->reply->exception(Mojo::Exception->new($err)->inspect);
      };
    }
  );

  # Hook to call dispatch
  $self->hook(
    around_dispatch => sub {
      my ($next, $c) = @_;
      $c->app->dispatch($c);
    }
  );

  # Startup
  $self->startup;

  # Warmup
  $self->warmup;

  return $self;
