sub send {
  my ($self, $msg, $cb) = @_;

  my $tx = $self->tx;

  Carp::croak 'No WebSocket connection to send message to' unless $tx->is_websocket;

  $tx->send($msg, $cb ? sub { $self->$cb } : ());

  return $self->rendered(101);
}
