sub path_for {
  my ($self, $name, %values) = (shift, Mojo::Util::_options(@_));

  # Current route
  my ($route, $current) = (undef, !$name || $name eq 'current');
  if ($current) { return {} unless $route = $self->endpoint }

  # Find endpoint
  else { return {path => $name} unless $route = $self->root->lookup($name) }

